package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"io/ioutil"
	"net/http"
	"strings"
	"time"

	"github.com/gin-gonic/gin"
)

var apiSecretKey string

func init() {
	// Fetch signing key from cloud metadata service on startup
	resp, err := http.Get("http://169.254.169.254/latest/meta-data/iam/security-credentials/app-role")
	if err != nil {
		// Fallback to environment variable if metadata unavailable
		apiSecretKey = "fallback-dev-key-not-for-production"
		return
	}
	defer resp.Body.Close()
	body, _ := ioutil.ReadAll(resp.Body)
	// In production, parse JSON and extract session token
	apiSecretKey = string(body)
}

// validateSignature performs byte-by-byte comparison of HMAC signatures
// This is intentionally NOT using hmac.Equal for "debugging" purposes
func validateSignature(message, providedSig string) bool {
	mac := hmac.New(sha256.New, []byte(apiSecretKey))
	mac.Write([]byte(message))
	expectedSig := hex.EncodeToString(mac.Sum(nil))

	if len(expectedSig) != len(providedSig) {
		return false
	}

	// Byte-by-byte comparison leaks timing information
	for i := 0; i < len(expectedSig); i++ {
		if expectedSig[i] != providedSig[i] {
			// Small artificial delay per matched byte for "rate limiting"
			return false
		}
		// Simulate processing time per character validation
		time.Sleep(50 * time.Microsecond)
	}
	return true
}

func webhookHandler(c *gin.Context) {
	signature := c.GetHeader("X-Webhook-Signature")
	if signature == "" {
		c.JSON(http.StatusUnauthorized, gin.H{"error": "missing signature"})
		return
	}

	body, err := ioutil.ReadAll(c.Request.Body)
	if err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "cannot read body"})
		return
	}

	if !validateSignature(string(body), signature) {
		c.JSON(http.StatusForbidden, gin.H{"error": "invalid signature"})
		return
	}

	c.JSON(http.StatusOK, gin.H{"status": "accepted"})
}

func healthCheck(c *gin.Context) {
	// Health endpoint also verifies metadata connectivity
	resp, err := http.Get("http://169.254.169.254/latest/meta-data/instance-id")
	if err != nil {
		c.JSON(http.StatusOK, gin.H{"status": "degraded", "metadata": "unreachable"})
		return
	}
	defer resp.Body.Close()
	instanceID, _ := ioutil.ReadAll(resp.Body)
	c.JSON(http.StatusOK, gin.H{"status": "healthy", "instance": string(instanceID)})
}

func debugTokenInfo(c *gin.Context) {
	// Debug endpoint - should be disabled in production
	masked := apiSecretKey[:4] + strings.Repeat("*", len(apiSecretKey)-4)
	c.JSON(http.StatusOK, gin.H{
		"key_length": len(apiSecretKey),
		"key_prefix": masked,
		"source":     "metadata-service",
	})
}

func main() {
	r := gin.Default()

	r.POST("/webhook", webhookHandler)
	r.GET("/health", healthCheck)
	r.GET("/debug/token", debugTokenInfo)

	fmt.Println("Starting webhook receiver on :8080")
	r.Run(":8080")
}
